ee: { loginSubj: "Woezɔ le App Pay – Wò ŋkɔŋlɔɖi na wòage ɖe eme", loginGreet: "Lɔ̃lɔ̃xɔ {name},", loginIntro: "Míekpɔ dzidzɔ be míagblɔ na wò be wò akɔnta ʋu le App Pay. Esiawoe nye wò ŋkɔŋlɔɖi na wòage ɖe eme:", loginFooter: "Le wò dedienɔnɔ ta, xɔ ŋkɔŋlɔɖi siawo ɖe to. Mègagblɔ wò PIN kɔdu na ame aɖeke o.", actSubj: "Wò kɔdu na App Pay gaɖɔɖɔ", actGreet: "Lɔ̃lɔ̃xɔ {name},", actIntro: "Be wò asitsalawo nanɔ dedie, kpɔ wò ŋutɔ ŋutɔ kɔdu le ete:", actFooter: "Xɔ kɔdu sia ɖe teƒe bɔbɔe. Ezɔ na wò ŋutɔ eye wòle ɣaɣa me.", successSubj: "Wò App Pay gaɖɔɖɔ ƒe nyatakaka", successGreet: "Lɔ̃lɔ̃xɔ {name},", successIntro: "Míegblɔ na wò be wò gaɖɔɖɔ wu enu nyuie. Esiawoe nye eta:", successFooter: "Woaxe ga la aɖe amesi axɔe la ƒe akɔnta me le gaƒoƒo 24 va ɖo 48 me. Míeda akpe na wò xɔse ta.", failedSubj: "Nuxlɔ̃ame: Wote wò App Pay gaɖɔɖɔ ɖa", failedGreet: "Lɔ̃lɔ̃xɔ {name},", failedIntro: "Míaƒe dedienɔnɔ ɖoɖowo te gaɖɔɖɔ ƒe tɔtrɔ si wowɔ le wò akɔnta me ɖa. Esiawoe nye nyatakakawo:", failedFooter: "Wometɔ ga aɖeke o. Taflatse yrɔ míaƒe asitsalawo.", pendingSubj: "Wò App Pay gaɖɔɖɔ le lalam", pendingGreet: "Lɔ̃lɔ̃xɔ {name},", pendingIntro: "Woŋlɔ wò gaɖɔɖɔ ɖi, eye wòle lalam na míaƒe dɔwɔlawo ƒe ɖoɖo.", pendingFooter: "Àxɔ gbeɖiɖi ne woɖo gaɖɔɖɔ la ɖe go.", validatedSubj: "Woɖo gaɖɔɖɔ ɖe go le dɔwɔlawo gbɔ", validatedGreet: "Lɔ̃lɔ̃xɔ {name},", validatedIntro: "Woxɔ wò gaɖɔɖɔ si le lalam la ɖe go le míaƒe dɔwɔlawo gbɔ eye wowu enu nyuie.", validatedFooter: "Woaxe ga la aɖe amesi axɔe la ƒe akɔnta me le gaƒoƒo 24 va ɖo 48 me. Míeda akpe na wò xɔse ta.", cancelledSubj: "Wote gaɖɔɖɔ ɖa le dɔwɔlawo gbɔ", cancelledGreet: "Lɔ̃lɔ̃xɔ {name},", cancelledIntro: "Míaƒe dɔwɔlawo te wò gaɖɔɖɔ ɖa. Wotrɔ ga la yi wò akɔnta me.", cancelledFooter: "Àte ŋu akpɔ wò ga yeye le wò asitsalawo ƒe mɔnu dzi.", refundSubj: "Wotrɔ gaɖɔɖɔ ɖa", refundGreet: "Lɔ̃lɔ̃xɔ {name},", refundIntro: "Míegblɔ na wò be wotrɔ wò gaɖɔɖɔ ƒe ga la na wò. Esiawoe nye nyatakakawo:", refundFooter: "Wotrɔ ga la yi wò akɔnta me. Míeda akpe na wò nɔnɔme ta.", userCancelledSubj: "Wote gaɖɔɖɔ ɖa", userCancelledGreet: "Lɔ̃lɔ̃xɔ {name},", userCancelledIntro: "Míegblɔ na wò be wote wò gaɖɔɖɔ ɖa. Wometɔ ga aɖeke le wò akɔnta me o.", userCancelledFooter: "Ne nyemie nye amesiwo bɔbɔ ɖeɖe sia gɔme o la, taflatse yrɔ míaƒe asitsalawo enumake.", adminConnectionSubj: "Asitsala yeye ƒe kadodo le App Pay", adminConnectionGreet: "Hello Admin,", adminConnectionIntro: "Asitsala si gbɔna la ƒe App Pay akɔnta me gbɔ loo. Esiawoe nye kadodo ƒe nyatakakawo:", adminConnectionFooter: "Woɖoa email sia ɖa na Admin zi ɖekaɖeka si asitsala aɖe age ɖe eme." },
ff: { loginSubj: "A jaaraama e App Pay – Ɗiɗi maa naatgol", loginGreet: "Giɗo {name},", loginIntro: "Meɗi weltaare hollirde maa woniima konte maa to e App Pay. Ɗiɗi maa naatgol:", loginFooter: "Yo bata kisal maa, reenu ɗi kabaruuji ɗi e suuɗe. Wataa hintin PIN maa e ne goɗɗo.", actSubj: "Kood maa ceede neldugol e App Pay", actGreet: "Giɗo {name},", actIntro: "Yo bata kisal njulaagu maa, ndaar kood maa keerol ɗoo les:", actFooter: "Reenu kood oo to nokku hisnii. Ko maa woni kadi ko suuɗii.", successSubj: "Tabitinde ceede neldugol maa e App Pay", successGreet: "Giɗo {name},", successIntro: "Men tabintinii woni ceede neldugol maa waɗaama no haani. Ɗiɗi ko fottu:", successFooter: "Ceede ɗe naatoytee e konte jaɓoowo o nder waktuuji 24 haa 48. A jaaraama e hoolaare maa.", failedSubj: "Reentaare: Ceede neldugol maa e App Pay haɗaama", failedGreet: "Giɗo {name},", failedIntro: "Yuɓɓo kisal amen haɗii ƴeewndo ceede neldugol e konte maa. Ɗiɗi ko ɓaŋŋe:", failedFooter: "Alaa ceede ɗe ƴeewaani. Tiiɗno yeŋtu e sarwiis jaɓoowo.", pendingSubj: "Ceede neldugol maa e App Pay ina fadii teeŋtingol", pendingGreet: "Giɗo {name},", pendingIntro: "Ceede neldugol maa winndaama tee ina fadii teeŋtingol e sarwiis men njuɓɓudi.", pendingFooter: "A heɓoyay habaru so tawii ceede ɗe njogii.", validatedSubj: "Ceede neldugol teeŋtinɗo e njuɓɓudi", validatedGreet: "Giɗo {name},", validatedIntro: "Ceede neldugol maa fadiiɗo teeŋtinii e sarwiis men njuɓɓudi tee waɗiraa no haani.", validatedFooter: "Ceede ɗe naatoytee e konte jaɓoowo o nder waktuuji 24 haa 48. A jaaraama e hoolaare maa.", cancelledSubj: "Ceede neldugol momtaa e njuɓɓudi", cancelledGreet: "Giɗo {name},", cancelledIntro: "Sarwiis men njuɓɓudi momtii ceede neldugol maa. Ceede ɗe ruttinaa e konte maa.", cancelledFooter: "A waawi ndaarde ceede maa kese e nder portal jaɓoowo maa.", refundSubj: "Ceede neldugol ruttinaama", refundGreet: "Giɗo {name},", refundIntro: "Men habri maa ceede neldugol maa ruttinaama e maaɗa. Ɗiɗi ko ɓaŋŋe:", refundFooter: "Ceede ɗe ruttinaa e konte maa. A jaaraama e faamu maa.", userCancelledSubj: "Ceede neldugol momtaama", userCancelledGreet: "Giɗo {name},", userCancelledIntro: "Men tabintinii woni ceede neldugol maa momtaama. Alaa ceede ɗe ƴeewaani e konte maa.", userCancelledFooter: "So wonaa an fuɗɗii momtugol ngol, tiiɗno yeŋtu e sarwiis jaɓoowo amen law.", adminConnectionSubj: "Jokkuɗo jaɓoowo keso e App Pay", adminConnectionGreet: "Salaam Admin,", adminConnectionIntro: "Jaɓoowo garoowo oo naatii jooni e App Pay maa. Ɗiɗi ko ɓaŋŋe jokkuɗo:", adminConnectionFooter: "Email oo neldee e Admin kala sahaa jaɓoowo naatii." },
