st: { loginSubj: "O amohelehile ho App Pay – Lintlha tsa hao tsa ho kena", loginGreet: "Moratuwa {name},", loginIntro: "Re thabile ho netefatsa hore akhaonto ya hao e butsoe ho App Pay. Tsena ke lintlha tsa hao tsa ho kena:", loginFooter: "Bakeng sa tshireletso ya hao, boloka lintlha tsena e le lekunutu. O se ke wa arolelana khoutu ya hao ya PIN le mang kapa mang.", actSubj: "Khoutu ya hao ya ho bula bakeng sa ho fetisa ho App Pay", actGreet: "Moratuwa {name},", actIntro: "Ho netefatsa tshireletso ya ditshebetsho tsa hao, ka kopo bona khoutu ya hao ya lekunutu ka tlase:", actFooter: "Boloka khoutu ena sebakeng se sireletsehileng. Ke ya hao feela mme ke lekunutu.", successSubj: "Netefatso ya ho fetisa ha hao ho App Pay", successGreet: "Moratuwa {name},", successIntro: "Re netefatsa hore ho fetisa ha hao ho phethilwe ka katleho. Tsena ke kakaretso:", successFooter: "Chelete e tla kena akhaontong ya moamoheli nakong ya dihora tse 24 ho isa ho tse 48 tsa mosebetsi. Rea leboha ka tshepo ya hao.", failedSubj: "Temoso: Ho fetisa ha hao ho App Pay ho thibetswe", failedGreet: "Moratuwa {name},", failedIntro: "Boiteko ba ho fetisa akhaontong ya hao bo thibetswe ke mekgwa ya rona ya tshireletso. Tsena ke dintlha:", failedFooter: "Ha ho chelete e tlositsweng. Ka kopo ikopanye le basebeletsi ba rona.", pendingSubj: "Ho fetisa ha hao ho App Pay ho letetse netefatso", pendingGreet: "Moratuwa {name},", pendingIntro: "Ho fetisa ha hao ho ngodisitswe mme ha jwale ho letetse netefatso ho tswa lekaleng la rona la tsamaiso.", pendingFooter: "O tla fumana tsebiso hang ha ho fetisa ho sebeditswe.", validatedSubj: "Ho fetisa ho netefaditswe ke tsamaiso", validatedGreet: "Moratuwa {name},", validatedIntro: "Ho fetisa ha hao ho neng ho letetse ho netefaditswe ke lekaleng la rona la tsamaiso mme ho phethilwe ka katleho.", validatedFooter: "Chelete e tla kena akhaontong ya moamoheli nakong ya dihora tse 24 ho isa ho tse 48 tsa mosebetsi. Rea leboha ka tshepo ya hao.", cancelledSubj: "Ho fetisa ho hlakotswe ke tsamaiso", cancelledGreet: "Moratuwa {name},", cancelledIntro: "Ho fetisa ha hao ho hlakotswe ke lekaleng la rona la tsamaiso. Chelete e kgutilsitswe akhaontong ya hao.", cancelledFooter: "O ka hlahloba chelete ya hao e ntjha portaleng ya hao ya moreki.", refundSubj: "Ho fetisa ho buseditswe", refundGreet: "Moratuwa {name},", refundIntro: "Chelete ya ho fetisa ha hao e buseditswe ho wena. Tsena ke dintlha:", refundFooter: "Chelete e kgutilsitswe akhaontong ya hao. Rea leboha ka kutlwisiso ya hao.", userCancelledSubj: "Ho fetisa ho hlakotswe", userCancelledGreet: "Moratuwa {name},", userCancelledIntro: "Re netefatsa hore ho fetisa ha hao ho hlakotswe. Ha ho chelete e tlositsweng akhaontong ya hao.", userCancelledFooter: "Haeba e se wena ya qadileng ho hlakola hona, ka kopo ikopanye le basebeletsi ba rona hang-hang.", adminConnectionSubj: "Kgokahanyo e ntjha ya moreki ho App Pay", adminConnectionGreet: "Dumela Motsamaisi,", adminConnectionIntro: "Moreki eo e latelang o sa tswa kena akhaontong ya hae ya App Pay. Tsena ke dintlha tsa kgokahanyo:", adminConnectionFooter: "Imeile ena e romelwa ho Motsamaisi ka boiketsetso nako e nngwe le e nngwe ha moreki a kena." },
