is: { loginSubj: "Velkomin í App Pay – Innskráningarupplýsingar þínar", loginGreet: "Kæri/Kæra {name},", loginIntro: "Við erum ánægð að staðfesta opnun reikningsins þíns hjá App Pay. Hér eru innskráningarupplýsingarnar þínar:", loginFooter: "Fyrir öryggi þitt mælum við með að halda þessum upplýsingum trúnaði. Deildu aldrei PIN-kóðanum þínum.", actSubj: "Virkjunarkóðinn þinn fyrir App Pay millifærslur", actGreet: "Kæri/Kæra {name},", actIntro: "Til að tryggja öryggi viðskipta þinna, vinsamlegast sjáðu persónulega virkjunarkóðann þinn hér að neðan:", actFooter: "Geymdu þennan kóða á öruggum stað. Hann er stranglega persónulegur og trúnaðarmál.", successSubj: "Staðfesting á App Pay millifærslunni þinni", successGreet: "Kæri/Kæra {name},", successIntro: "Við staðfestum að millifærslan þín hefur verið unnin með góðum árangri. Hér er samantektin:", successFooter: "Fjármunirnir verða lagðir inn á reikning viðtakandans innan 24 til 48 bankadaga. Takk fyrir traustið.", failedSubj: "Viðvörun: App Pay millifærslan þín var lokuð", failedGreet: "Kæri/Kæra {name},", failedIntro: "Tilraun til millifærslu á reikninginn þinn var lokuð af öryggiskerfum okkar. Hér eru upplýsingarnar:", failedFooter: "Ekkert upphæð var dregin. Vinsamlegast hafðu samband við þjónustuver.", pendingSubj: "App Pay millifærslan þín bíður staðfestingar", pendingGreet: "Kæri/Kæra {name},", pendingIntro: "Millifærslan þín hefur verið skráð og bíður nú staðfestingar frá stjórnsýsluþjónustu okkar.", pendingFooter: "Þú munt fá tilkynningu um leið og millifærslan hefur verið unnin.", validatedSubj: "Millifærsla staðfest af stjórnendum", validatedGreet: "Kæri/Kæra {name},", validatedIntro: "Millifærslan þín í bið hefur verið staðfest af stjórnsýsluþjónustu okkar og unnin með góðum árangri.", validatedFooter: "Fjármunirnir verða lagðir inn á reikning viðtakandans innan 24 til 48 bankadaga. Takk fyrir traustið.", cancelledSubj: "Millifærsla afturkölluð af stjórnendum", cancelledGreet: "Kæri/Kæra {name},", cancelledIntro: "Millifærslan þín hefur verið afturkölluð af stjórnsýsluþjónustu okkar. Upphæðin hefur verið lögð aftur inn á reikninginn þinn.", cancelledFooter: "Þú getur athugað nýja stöðu þína í viðskiptavinagáttinni þinni.", refundSubj: "Millifærsla endurgreidd", refundGreet: "Kæri/Kæra {name},", refundIntro: "Upphæð millifærslunnar þinnar hefur verið endurgreidd til þín. Hér eru upplýsingarnar:", refundFooter: "Upphæðin hefur verið lögð aftur inn á reikninginn þinn. Takk fyrir skilninginn.", userCancelledSubj: "Millifærsla afturkölluð", userCancelledGreet: "Kæri/Kæra {name},", userCancelledIntro: "Við staðfestum að millifærslan þín hefur verið afturkölluð. Ekkert upphæð var dregin af reikningnum þínum.", userCancelledFooter: "Ef þú hófst ekki þessa afturköllun, vinsamlegast hafðu strax samband við þjónustuver okkar.", adminConnectionSubj: "Ný tenging viðskiptavinar á App Pay", adminConnectionGreet: "Halló Stjórnandi,", adminConnectionIntro: "Eftirfarandi viðskiptavinur skráði sig rétt í þessu inn á App Pay reikninginn sinn. Hér eru upplýsingar um tenginguna:", adminConnectionFooter: "Þetta tölvupóstur er sjálfkrafa sent til stjórnandans í hvert skipti sem viðskiptavinur skráir sig inn." },
