    ty: { loginSubj: "Maeva i App Pay – Tō tāpura no te tomora'a", loginGreet: "Here {name},", loginIntro: "Te oaoa nei mātou i te fa'ā'āpo'ora'a i te iritira'a o tō wōna i roto i App Pay. Teie tō tāpura no te tomora'a:", loginFooter: "No tō paruruhia, e tītauhia ia tō parau nei. 'Aita e tāviri i tō pāpa'i PIN i te tahi atu ta'ata.", actSubj: "Tō pāpa'i fa'a'āpo'ora'a no te mau fa'ahoro'a App Pay", actGreet: "Here {name},", actIntro: "No te paruruhia o tā'u mau 'ohipa, teie tō pāpa'i fa'a'āpo'ora'a iā'na i raro nei:", actFooter: "Tāpura i teie pāpa'i i te hoê vāhi paruruhia. E mea tā'u iho e mea huna.", successSubj: "Fa'ā'āpo'ora'a o tō fa'ahoro'a App Pay", successGreet: "Here {name},", successIntro: "Te fa'ā'āpo'ora'a nei mātou ua oti tō fa'ahoro'a i te rave ma te manuia. Teie te ha'apotora'a:", successFooter: "E tono te moni i roto i te wōna o te ta'ata e fāri'i i roto i te 24 e tae noa'tu i te 48 hora ohipa. Māuruuru i tō ti'aturi.", failedSubj: "Ha'apā'ira'a: Ua 'āpā tō fa'ahoro'a App Pay", failedGreet: "Here {name},", failedIntro: "Ua 'āpā te hoê tamata fa'ahoro'a i tō wōna e tō mātou mau fa'anahora'a paruruhia. Teie te mau parau:", failedFooter: "'Aita e moni i 'ohi. Tāviri atu i te tavinira'a o te mau kiritiāni.", pendingSubj: "Tō fa'ahoro'a App Pay e tiai nei i te fa'ā'āpo'ora'a", pendingGreet: "Here {name},", pendingIntro: "Ua papa'ihia tō fa'ahoro'a, e i teie nei te tiai nei i te fa'ā'āpo'ora'a a tō mātou tavinira'a fa'atere.", pendingFooter: "E fāri'i 'oe i te hoê fa'ā'ite i te taime e oti ai te fa'ahoro'a.", validatedSubj: "Ua fa'ā'āpo'ora'ahia te fa'ahoro'a e te fa'atere", validatedGreet: "Here {name},", validatedIntro: "Ua fa'ā'āpo'ora'ahia tō fa'ahoro'a e tō mātou tavinira'a fa'atere, e ua oti i te rave ma te manuia.", validatedFooter: "E tono te moni i roto i te wōna o te ta'ata e fāri'i i roto i te 24 e tae noa'tu i te 48 hora ohipa. Māuruuru i tō ti'aturi.", cancelledSubj: "Ua fa'aruehia te fa'ahoro'a e te fa'atere", cancelledGreet: "Here {name},", cancelledIntro: "Ua fa'aruehia tō fa'ahoro'a e tō mātou tavinira'a fa'atere. Ua fa'aho'i te moni i roto i tō wōna.", cancelledFooter: "E nehenehe 'oe e hi'o i tō anaira'a apī i roto i tō tomora'a kiritiāni.", refundSubj: "Ua fa'aho'ihia te fa'ahoro'a", refundGreet: "Here {name},", refundIntro: "Te fa'ā'ite nei mātou ua fa'aho'ihia te moni o tō fa'ahoro'a iā 'oe. Teie te mau parau:", refundFooter: "Ua fa'aho'ihia te moni i roto i tō wōna. Māuruuru i tō taa.", userCancelledSubj: "Ua fa'aruehia te fa'ahoro'a", userCancelledGreet: "Here {name},", userCancelledIntro: "Te fa'ā'āpo'ora'a nei mātou ua fa'aruehia tō fa'ahoro'a. 'Aita e moni i 'ohi mai i tō wōna.", userCancelledFooter: "Ia 'ore 'oe tei ha'amata i teie fa'arue, tāviri wawe atu i tā mātou tavinira'a kiritiāni.", adminConnectionSubj: "Ta'atira'a apī o te kiritiāni i App Pay", adminConnectionGreet: "Ia ora na e te Fa'atere,", adminConnectionIntro: "Ua tomora'a teie kiritiāni i tōna wōna App Pay. Teie te mau parau o te ta'atira'a:", adminConnectionFooter: "E tono-auto-teie īmēra i te Fa'atere i te mau taime ato'a e tomora'a ai te hoê kiritiāni." },
    tl: { loginSubj: "Maligayang pagdating sa App Pay – Ang iyong mga kredensyal sa pag-login", loginGreet: "Mahal na {name},", loginIntro: "Ikinalulugod naming kumpirmahin ang pagbubukas ng iyong account sa App Pay. Narito ang iyong mga kredensyal sa pag-login:", loginFooter: "Para sa iyong seguridad, itago ang impormasyong ito nang kumpidensyal. Huwag kailanman ibahagi ang iyong PIN code.", actSubj: "Ang iyong activation code para sa mga paglilipat ng App Pay", actGreet: "Mahal na {name},", actIntro: "Upang matiyak ang seguridad ng iyong mga transaksyon, paki-tingnan ang iyong personal na activation code sa ibaba:", actFooter: "Itago ang code na ito sa isang ligtas na lugar. Ito ay mahigpit na personal at kumpidensyal.", successSubj: "Kumpirmasyon ng iyong paglilipat sa App Pay", successGreet: "Mahal na {name},", successIntro: "Kinukumpirma namin na ang iyong paglilipat ay matagumpay na naproseso. Narito ang buod:", successFooter: "Ang mga pondo ay ikredito sa account ng benepisyaryo sa loob ng 24 hanggang 48 oras ng negosyo. Salamat sa iyong tiwala.", failedSubj: "Babala: Ang iyong paglilipat sa App Pay ay na-block", failedGreet: "Mahal na {name},", failedIntro: "Ang isang pagtatangkang paglilipat sa iyong account ay na-block ng aming mga sistema ng seguridad. Narito ang mga detalye:", failedFooter: "Walang halagang na-debit. Mangyaring makipag-ugnayan sa customer service para sa karagdagang impormasyon.", pendingSubj: "Ang iyong paglilipat sa App Pay ay nakabinbin para sa validation", pendingGreet: "Mahal na {name},", pendingIntro: "Ang iyong paglilipat ay nairehistro at kasalukuyang nakabinbin para sa validation ng aming serbisyong administratibo.", pendingFooter: "Makakatanggap ka ng notification sa sandaling maproseso ang paglilipat.", validatedSubj: "Ang paglilipat ay na-validate ng administrasyon", validatedGreet: "Mahal na {name},", validatedIntro: "Ang iyong nakabinbing paglilipat ay na-validate ng aming serbisyong administratibo at matagumpay na naproseso.", validatedFooter: "Ang mga pondo ay ikredito sa account ng benepisyaryo sa loob ng 24 hanggang 48 oras ng negosyo. Salamat sa iyong tiwala.", cancelledSubj: "Ang paglilipat ay kinansela ng administrasyon", cancelledGreet: "Mahal na {name},", cancelledIntro: "Ang iyong paglilipat ay kinansela ng aming serbisyong administratibo. Ang halaga ay naikredito pabalik sa iyong account.", cancelledFooter: "Maaari mong suriin ang iyong bagong balanse sa iyong portal ng kliyente.", refundSubj: "Ang paglilipat ay naibalik", refundGreet: "Mahal na {name},", refundIntro: "Ang halaga ng iyong paglilipat ay naibalik sa iyo. Narito ang mga detalye:", refundFooter: "Ang halaga ay naikredito pabalik sa iyong account. Salamat sa iyong pag-unawa.", userCancelledSubj: "Kinansela ang paglilipat", userCancelledGreet: "Mahal na {name},", userCancelledIntro: "Kinukumpirma namin na ang iyong paglilipat ay kinansela. Walang halagang na-debit mula sa iyong account.", userCancelledFooter: "Kung hindi ikaw ang nagpasimula ng pagkanselang ito, mangyaring makipag-ugnayan kaagad sa aming customer service.", adminConnectionSubj: "Bagong koneksyon ng kliyente sa App Pay", adminConnectionGreet: "Kamusta Administrator,", adminConnectionIntro: "Ang sumusunod na kliyente ay karapatan lang na nag-log in sa kanilang App Pay account. Narito ang mga detalye ng koneksyon:", adminConnectionFooter: "Ang email na ito ay awtomatikong ipinapadala sa administrator sa tuwing mag-log in ang isang kliyente." },
